COST_PER_1K = {
    "deepseek": (0.001, 0.003),
    "xiaomi": (0.001, 0.003),
    "ollama": (0, 0),
    "anthropic": (0.003, 0.015),
}


def _estimate_cost(input_tok: int, output_tok: int, provider: str) -> float:
    rates = COST_PER_1K.get(provider, (0, 0))
    return (input_tok / 1000 * rates[0]) + (output_tok / 1000 * rates[1])


